# Where the "Выбрать школу" button sends a lead once a school's sales team agrees to take
# direct traffic from us (their own sales page, CRM form, phone/chat link — whatever they want).
# Empty until a deal is negotiated; a school with no entry here falls back to its official_url
# with UTM tags, so the button always has somewhere to go.
LEAD_URLS = {}
for _school in SEED:
    _status = CRITERIA_STATUS.get(_school["name"], {})
    _school["criteria_status"] = json.dumps(_status, ensure_ascii=False, sort_keys=True)
    for _key, _value in _status.items():
        if _value == "none":
            _school[_key] = 0.0   # placeholder: ignored everywhere, 0 makes any leak obvious


# Keep base and profile separate in every consumer of this catalogue.
for school in SEED:
    subjects = ["математика профильная" if item == "математика" else item for item in school["subjects"].split(",")]
    if school["name"] in BASE_SCHOOL_SOURCES:
        subjects.insert(subjects.index("математика профильная") + 1, "математика базовая")
    school["subjects"] = ",".join(subjects)
TEACHERS = [(school, name, teacher_exam_subject(school, name, subject), *rest)
            for school, name, subject, *rest in TEACHERS]

