async def _upsert_schools(session: AsyncSession):
    for item in SEED:
        school = (await session.execute(select(School).where(School.name == item["name"]))).scalar_one_or_none()
        if school is None:
            school = School(**item)
            session.add(school)
            continue
        for key, value in item.items():
            setattr(school, key, value)
    await session.commit()


async def _upsert_teachers(session: AsyncSession):
    schools = {row.name: row.id for row in (await session.execute(select(School))).scalars().all()}
    # Preserve reviews and ratings when a researched card gains a full name or
    # the current subject lead replaces an outdated catalog entry.
    for (school_name, old_name, subject), new_name in TEACHER_RENAMES.items():
        school_id = schools.get(school_name)
        if not school_id:
            continue
        old_teacher = (await session.execute(select(Teacher).where(
            Teacher.school_id == school_id,
            Teacher.name == old_name,
            Teacher.subject == subject,
        ))).scalar_one_or_none()
        new_teacher = (await session.execute(select(Teacher).where(
            Teacher.school_id == school_id,
            Teacher.name == new_name,
            Teacher.subject == subject,
        ))).scalar_one_or_none()
        if old_teacher and new_teacher is None:
            old_teacher.name = new_name
        elif old_teacher and new_teacher:
            old_teacher.is_active = False
    await session.flush()
    for school_name, name, subject, description, rating, review_summary, source_url in TEACHERS:
        school_id = schools.get(school_name)
        if not school_id:
            continue
        teacher = (await session.execute(select(Teacher).where(Teacher.school_id == school_id, Teacher.name == name, Teacher.subject == subject))).scalar_one_or_none()
        values = dict(school_id=school_id, name=name, subject=subject, description=description, rating=rating,
                      review_summary=review_summary, social_url=TEACHER_SOCIALS.get((school_name, name), ""),
                      source_url=source_url, evidence_type="карточка курса/профиль/соцсеть", is_active=True)
        if teacher is None:
            session.add(Teacher(**values))
        else:
            for key, value in values.items():
                setattr(teacher, key, value)
    for school_name, name, subject in REMOVED_TEACHERS:
        stale = (await session.execute(select(Teacher).where(
            Teacher.school_id == schools.get(school_name), Teacher.name == name, Teacher.subject == subject,
        ))).scalar_one_or_none()
        if stale is not None:
            stale.is_active = False
    await session.commit()


async def _upsert_courses(session: AsyncSession):
    """Create subject-level course cards from current school-level research.

    Price and tariff text is intentionally repeated only when the school publishes
    one offer for the subject range. Precise subject/tariff research can replace
    these rows later without changing the user flow.
    """
    schools = (await session.execute(select(School))).scalars().all()
    checked_at = datetime(2026, 9, 13)
    for school in schools:
        config = COURSE_CONFIG.get(school.name)
        if not config:
            continue
        for subject in (item.strip() for item in school.subjects.split(",") if item.strip()):
            subject_name = subject.capitalize()
            override = COURSE_OVERRIDES.get((school.name, subject_name), {})
            course_config = {**config, **override}
            if subject == "математика базовая":
                course_config = {**course_config, "name": "Подготовка к ЕГЭ · базовая математика",
                    "price_from": 0, "price_text": "Стоимость курса базовой математики уточняется отдельно; цена школы может относиться к другому предмету.",
                    "format_text": "Подготовка к отдельному экзамену по базовой математике. Сроки и расписание уточни на странице курса.",
                    "support_text": "Наличие куратора и условия проверки зависят от выбранного тарифа.",
                    "practice_text": "Задания и пробные варианты базового уровня ЕГЭ.",
                    "tariffs": [], "source_url": BASE_SCHOOL_SOURCES[school.name]}
            name = course_config["name"]
            if subject_name not in name:
                name = f"{name} · {subject_name}"
            course = (await session.execute(
                select(Course).where(
                    Course.school_id == school.id,
                    Course.subject == subject_name,
                )
            )).scalar_one_or_none()
            values = {
                "school_id": school.id,
                "subject": subject_name,
                "name": name,
                "price_from": course_config["price_from"],
                "price_text": course_config["price_text"],
                "format_text": course_config["format_text"],
                "support_text": course_config["support_text"],
                "practice_text": course_config["practice_text"],
                "tariffs_json": json.dumps(course_config["tariffs"], ensure_ascii=False),
                "source_url": course_config.get("source_url", school.official_url),
                "verified_at": checked_at,
                "is_active": True,
            }
            if course is None:
                session.add(Course(**values))
            else:
                for key, value in values.items():
                    setattr(course, key, value)
    await session.commit()


async def _remove_expired_proofs(session: AsyncSession):
    """Proof files are only needed for moderation and should not live indefinitely."""
    expired = (await session.execute(
        select(Review).where(
            Review.proof_file_id.is_not(None),
            Review.proof_delete_after.is_not(None),
            Review.proof_delete_after <= datetime.utcnow(),
        )
    )).scalars().all()
    for review in expired:
        review.proof_file_id = None
        review.proof_file_type = None
        review.proof_delete_after = None
    if expired:
        await session.commit()


async def cleanup_expired_proofs(session_factory):
    """Forget expired Telegram file references without touching review text."""
    async with session_factory() as session:
        await _remove_expired_proofs(session)


async def _remove_obsolete_teacher_rows(session: AsyncSession):
    """Remove records left by corrected research, so a wrong legacy card is not shown."""
    school_id = (await session.execute(select(School.id).where(School.name == "99 Баллов"))).scalar_one_or_none()
    if school_id:
        await session.execute(
            text("DELETE FROM teachers WHERE school_id = :school_id AND name = :name AND subject = :subject"),
            {"school_id": school_id, "name": "Ляйсан Хайбуллина", "subject": "Информатика"},
        )
    school_id = (await session.execute(select(School.id).where(School.name == "100балльный репетитор"))).scalar_one_or_none()
    if school_id:
        await session.execute(
            text("DELETE FROM teachers WHERE school_id = :school_id AND name = :name AND subject = :subject"),
            {"school_id": school_id, "name": "Маша Вайб", "subject": "Обществознание"},
        )
    await session.commit()


async def init_db(url: str, manage_schema: Optional[bool] = None):
    is_postgres = url.startswith(("postgresql+asyncpg://", "postgres+asyncpg://"))
    engine_options = {}
    if is_postgres:
        engine_options["connect_args"] = {"ssl": "require", "statement_cache_size": 0}
        engine_options["pool_size"] = 3
        engine_options["max_overflow"] = 2
        engine_options["pool_pre_ping"] = True
    engine = create_async_engine(url, **engine_options)
    if manage_schema is None:
        manage_schema = not is_postgres
    if manage_schema:
        async with engine.begin() as conn:
            await conn.run_sync(Base.metadata.create_all)
        await _ensure_school_columns(engine)
        await _ensure_review_columns(engine)
        await _ensure_user_columns(engine)
    session_factory = async_sessionmaker(engine, expire_on_commit=False)
    if not manage_schema:
        async with session_factory() as session:
            await _remove_expired_proofs(session)
        return engine, session_factory
    async with session_factory() as session:
        await _upsert_schools(session)
        # Update existing rows in place: teacher IDs and attached reviews survive.
        for teacher in (await session.execute(select(Teacher))).scalars():
            school_name = (await session.get(School, teacher.school_id)).name
            teacher.subject = teacher_exam_subject(school_name, teacher.name, teacher.subject)
        for course in (await session.execute(select(Course).where(Course.subject == "Математика"))).scalars():
            course.subject = "Математика профильная"
        await session.commit()
        await _upsert_teachers(session)
        await _upsert_courses(session)
        await _remove_obsolete_teacher_rows(session)
        await _remove_expired_proofs(session)
    return engine, session_factory


async def get_or_create_user(session: AsyncSession, telegram_id: int) -> User:
    user = (await session.execute(select(User).where(User.telegram_id == telegram_id))).scalar_one_or_none()
    if not user:
        user = User(telegram_id=telegram_id)
        session.add(user)
        await session.commit()
    return user


async def delete_user_data(session: AsyncSession, telegram_id: int) -> dict[str, int]:
    """Delete every row tied to a Telegram user and refresh public ratings.

    The operation is deliberately idempotent: asking twice leaves the database
    in the same state and reports zero deleted records on the second attempt.
    """
    user = (await session.execute(
        select(User).where(User.telegram_id == telegram_id)
    )).scalar_one_or_none()
    review_ids: list[int] = []
    if user:
        review_ids = list((await session.execute(
            select(Review.id).where(Review.user_id == user.id)
        )).scalars())
        if review_ids:
            await session.execute(
                delete(ReviewCriterionScore).where(ReviewCriterionScore.review_id.in_(review_ids))
            )
            await session.execute(delete(Review).where(Review.user_id == user.id))
        await session.delete(user)

    deleted_events = (await session.execute(
        delete(Event).where(Event.telegram_id == telegram_id)
    )).rowcount or 0
    await session.commit()

    # PostgreSQL serves cached snapshots to the website. Refresh them after an
    # approved review disappears so the public score does not stay stale until
    # the nightly job. SQLite is used locally and calculates ratings live.
    if session.bind and session.bind.dialect.name == "postgresql" and review_ids:
        try:
            await session.execute(text("select public.refresh_all_rating_snapshots()"))
            await session.commit()
        except Exception:
            # Deletion itself is already committed. The scheduled refresh is a
            # safe fallback if this database role cannot execute the function.
            await session.rollback()

    return {
        "users": 1 if user else 0,
        "reviews": len(review_ids),
        "events": int(deleted_events),
    }
